async def act(page):
    # Navigate directly to Shopping Cart Price Rules list (relative goto)
    await page.goto("/index.php/admin/promo_quote/")
    await page.wait_for_load_state("networkidle")

    # Click Add New Rule (try common role-based fallbacks)
    add_clicked = False
    # Try link first
    try:
        add_link = page.get_by_role("link", name="Add New Rule")
        if await add_link.count() > 0:
            await add_link.first().click()
            add_clicked = True
    except Exception:
        pass

    if not add_clicked:
        # Try button fallback
        try:
            add_button = page.get_by_role("button", name="Add New Rule")
            if await add_button.count() > 0:
                await add_button.first().click()
                add_clicked = True
        except Exception:
            pass

    # If still not clicked, try a more generic 'Add New' button
    if not add_clicked:
        try:
            add_button2 = page.get_by_role("button", name="Add New")
            if await add_button2.count() > 0:
                await add_button2.first().click()
                add_clicked = True
        except Exception:
            pass

    # Wait for the new rule form to load
    await page.wait_for_load_state("networkidle")

    # Fill Rule Name (try a few common label names)
    rule_name_candidates = ["Rule Name", "Name"]
    for candidate in rule_name_candidates:
        try:
            name_box = page.get_by_role("textbox", name=candidate)
            if await name_box.count() > 0:
                await name_box.first().fill("Mother's Day Sale")
                break
        except Exception:
            pass

    # Fill Description (try textarea as textbox may be used)
    desc_filled = False
    try:
        desc = page.get_by_role("textbox", name="Description")
        if await desc.count() > 0:
            await desc.first().fill("$15 discount on checkout for all customers. Mother's Day promotion.")
            desc_filled = True
    except Exception:
        pass
    if not desc_filled:
        try:
            desc_area = page.get_by_role("textbox").filter(has_text="Description")
            if await desc_area.count() > 0:
                await desc_area.first().fill("$15 discount on checkout for all customers. Mother's Day promotion.")
        except Exception:
            # last fallback: fill the first large textbox/textarea on the page if present
            try:
                all_textboxes = page.get_by_role("textbox")
                if await all_textboxes.count() > 1:
                    # assume second textbox could be description if first is name
                    await all_textboxes.nth(1).fill("$15 discount on checkout for all customers. Mother's Day promotion.")
            except Exception:
                pass

    # Ensure rule is Active if there is a combobox for Active
    try:
        active_combo = page.get_by_role("combobox", name="Active")
        if await active_combo.count() > 0:
            # Try selecting the typical "Active" -> "Yes" which often has value '1'
            try:
                await active_combo.first().select_option(value="1")
            except Exception:
                # fallback to label
                await active_combo.first().select_option(label="Yes")
    except Exception:
        pass

    # Check all checkboxes on the form (to include Websites and Customer Groups)
    try:
        checkboxes = page.get_by_role("checkbox")
        total = await checkboxes.count()
        for i in range(total):
            try:
                await checkboxes.nth(i).check()
            except Exception:
                # ignore if it cannot be checked or is disabled
                pass
    except Exception:
        pass

    # Set the action/apply combobox to fixed cart discount (try common names)
    try:
        apply_combo = page.get_by_role("combobox", name="Apply")
        if await apply_combo.count() == 0:
            apply_combo = page.get_by_role("combobox", name="Apply to")
        if await apply_combo.count() == 0:
            apply_combo = page.get_by_role("combobox", name="Action")
        if await apply_combo.count() > 0:
            # typical value for fixed cart amount is 'cart_fixed'
            try:
                await apply_combo.first().select_option(value="cart_fixed")
            except Exception:
                # try common label fallback
                for lbl in ["Fixed amount discount for whole cart", "Fixed amount", "Fixed"]:
                    try:
                        await apply_combo.first().select_option(label=lbl)
                        break
                    except Exception:
                        pass
    except Exception:
        pass

    # Fill Discount Amount
    try:
        disc_candidates = ["Discount Amount", "Discount", "Amount"]
        for c in disc_candidates:
            try:
                disc_box = page.get_by_role("textbox", name=c)
                if await disc_box.count() > 0:
                    await disc_box.first().fill("15")
                    break
            except Exception:
                pass
    except Exception:
        pass

    # Optionally set Priority if present
    try:
        priority = page.get_by_role("textbox", name="Priority")
        if await priority.count() > 0:
            await priority.first().fill("0")
    except Exception:
        pass

    # Save the rule. This will navigate away, so make it the last action.
    # Try common Save buttons/links
    save_clicked = False
    try:
        save_btn = page.get_by_role("button", name="Save Rule")
        if await save_btn.count() > 0:
            await save_btn.first().click()
            save_clicked = True
    except Exception:
        pass

    if not save_clicked:
        try:
            save_btn2 = page.get_by_role("button", name="Save")
            if await save_btn2.count() > 0:
                await save_btn2.first().click()
                save_clicked = True
        except Exception:
            pass

    if not save_clicked:
        # try a link fallback
        try:
            save_link = page.get_by_role("link", name="Save Rule")
            if await save_link.count() > 0:
                await save_link.first().click()
                save_clicked = True
        except Exception:
            pass

    # Wait for navigation to complete if we clicked save
    if save_clicked:
        await page.wait_for_load_state("networkidle")

